impl OriginalSameActorCJoined {
    /// Consume the actual C and Learning owner bundles only under the real
    /// same-peer Root Intent. No await or removable-owner gap occurs between
    /// those fields leaving CJoined and entering the returned custody.
    pub(crate) fn retire_original_root_purposes(
        self,
        intent: &crate::same_actor_q24_deployment::OriginalRootRetirementIntent,
    ) -> Result<OriginalSameActorCPurposesRetired, AgentdError> {
        OriginalSameActorCJoined::require_retained_original_owners(&self)?;
        crate::same_actor_q24_deployment::OriginalRootRetirementIntent::require_original_origin(
            intent,
            &self.original.origin.identity,
            &self.original.origin.gate,
        )?;
        let OriginalSameActorCJoined {
            original,
            route,
            work,
            learning,
        } = self;
        let learning = OriginalRetiredLearningOwners::retire_original_root_purposes(
            learning, intent,
        )?;
        crate::PublishedCircuitFeatureTaskV1::retire_original_root_current_after_intent(
            &OriginalQ24InstalledSuccessorV1::published_task(&original.installed),
            intent,
            &original.origin.identity,
            &original.origin.gate,
        )?;
        crate::same_actor_q24_deployment::OriginalRootRetirementIntent::require_original_origin(
            intent,
            &original.origin.identity,
            &original.origin.gate,
        )?;
        let retired = OriginalSameActorCPurposesRetired {
            original,
            route,
            work,
            learning,
        };
        OriginalSameActorCPurposesRetired::require_original_phase(
            &retired,
            &retired.original.origin.identity,
            &retired.original.origin.gate,
        )?;
        Ok(retired)
    }
}

impl OriginalSameActorCPurposesRetired {
    /// Validate the already sealed terminal route/slot and actual returned
    /// Learning owners. CURRENT and ordinary Session admission stay stopped.
    pub(crate) fn require_original_phase(
        &self,
        identity: &AgentdIdentity,
        gate: &Arc<SameActorPhaseGate>,
    ) -> Result<(), AgentdError> {
        let checked = (|| {
            self.original.origin.require_original_binding(identity, gate)?;
            self.original
                .slot
                .require_original_retired_slot(&self.original.origin)?;
            let route = self.original.origin.original_route()?;
            if !Arc::ptr_eq(&route, &self.route)
                || self.original.installed.identity != self.original.origin.identity
            {
                return Err(retirement_error("original C retired purpose custody differs"));
            }
            OriginalRetiredLearningPurposes::require_original_work(&self.learning, &self.work)?;
            let state = route.state.lock().map_err(|_| poisoned_route())?;
            if state.closed || state.tickets != 0 || !matches!(state.phase, Phase::RetiredC) {
                return Err(retirement_error("original C purpose route is not retired"));
            }
            self.original.origin.gate.require_open().map_err(phase_error)?;
            Ok(())
        })();
        if checked.is_err() {
            self.original.origin.gate.close();
        }
        checked
    }
}

